    "tour.hi.t":      "Light Plan",
    "tour.hi.d":      "Свет, погода и съёмки — в одном месте. Покажу за минуту и прямо на живом экране. Выйти можно на любом шаге.",
    "tour.dome.t":    "Купол света",
    "tour.dome.d":    "Дуга — путь солнца от восхода до заката, диск — где оно сейчас. Штрих вниз показывает высоту и длину тени.",
    "tour.time.t":    "Время в руке",
    "tour.time.d":    "Ползунок двигает время: купол, телеметрия и погода пересчитываются на выбранную минуту. Один и тот же ползунок на «Свете» и «Карте».",
    "tour.sky.t":     "Солнце или луна",
    "tour.sky.d":     "Тумблер меняет светило на куполе. У луны та же дуга, своя фаза и свои восход с заходом.",
    "tour.tele.t":    "Приборная панель",
    "tour.tele.d":    "Условия, закат, золотой час, свет, тени, небо, ветер. Строки меняются вместе со временем на ползунке.",
    "tour.place.t":   "Место съёмки",
    "tour.place.d":   "Свет считается там, где вы снимаете. Место меняется тапом по шапке — геопозицией, поиском или координатами.",
    "tour.map.t":     "Компас света",
    "tour.map.d":     "На карте видно, откуда светит солнце и куда ложится тень. Двигаете время — луч едет за ним.",
    "tour.cal.t":     "Календарь съёмок",
    "tour.cal.d":     "Месяц, неделя или один день. Жанр стоит прямо в клетке словом, а не значком.",
    "tour.stats.t":   "Год считает сам",
    "tour.stats.d":   "Календарь подводит итог за год: сколько снято и что впереди, по жанрам, со сроками сдачи и деньгами. Вводить отдельно ничего не нужно.",
    "tour.add.t":     "Первая съёмка",
    "tour.add.d":     "Кнопка заводит запись: дата, жанр, место, время начала. Дальше календарь и свет работают вместе.",
    "tour.bin.t":     "Корзина",
    "tour.bin.d":     "Удалённая съёмка не пропадает: она лежит в корзине и возвращается на своё место одной кнопкой. Строка появляется здесь, как только в корзине что-то есть.",
    "tour.mode.t":    "Просто и Астро",
    "tour.mode.d":    "«Просто» оставляет на экранах только нужное для съёмки. «Астро» добавляет азимуты, высоту солнца, длину тени, сумерки и ленту суток под ползунком.",
    "tour.cloud.t":   "Копия в облаке",
    "tour.cloud.d":   "Яндекс.Диск, Google или Dropbox: туда уходят копия данных и референсы съёмок. На наш сервер не уходит ничего.",
    "tour.end.t":     "Это всё",
